def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each nonzero source cell selects a block; that block contains the
    # source pattern's complement, in the selected cell's color.
    out = [[0 for _ in range(w * w)] for _ in range(h * h)]
    for br in range(h):
        for bc in range(w):
            color = grid[br][bc]
            if color == 0:
                continue
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == 0:
                        out[br * h + r][bc * w + c] = color
    return out
